    readings: [
      { key: 'sup', label: 'Supply air', value: 58, unit: '°F', jitter: 0.5, status: 'crit', expect: '95–120 °F in heating', after: 108 },
      { key: 'space', label: 'Space temperature at the front', value: 61, unit: '°F', jitter: 0.4, wander: 0.5, status: 'crit', expect: '70 °F', after: 70 },
      { key: 'micro', label: 'Flame signal', value: 0.3, unit: 'µA', decimals: 1, jitter: 0.05, status: 'crit', expect: '> 1.5 µA', after: 4.2 },
      { key: 'tries', label: 'Ignition attempts before lockout', value: 3, unit: '', jitter: 0, status: 'crit', expect: 'lights on the first try', after: 1 },
    ],
    checks: [
      { id: 'watch', label: 'Watch a full ignition sequence', tool: 'Eyes', minutes: 10, key: true, finding: 'Inducer proves, igniter glows, gas valve opens and the burners light cleanly — then the flame drops out after about four seconds. Three tries and it locks out.' },
      { id: 'flame', label: 'Read the flame signal in microamps', tool: 'Multimeter', minutes: 8, key: true, finding: '0.3 µA while the burners are actually alight. The board needs better than 1.5 µA to believe there is a flame, so it drops the valve.' },
      { id: 'rod', label: 'Inspect the flame rod and its ground', tool: 'Eyes', minutes: 6, key: true, finding: 'Rod is coated in grey-white oxide and the ceramic is sooty. The burner ground strap is intact and tight.' },
      { id: 'gas', label: 'Check gas pressure at the manifold', tool: 'Gauges / manual', minutes: 8, finding: 'Manifold pressure is on the nameplate value while the burners are lit. Gas supply is fine.' },
      { id: 'flue', label: 'Check the flue and the inducer', tool: 'Eyes', minutes: 6, finding: 'Flue is clear, inducer wheel is clean and the pressure switch makes and holds. Nothing wrong with the draught.' },
    ],
    causes: [
      { id: 'rod', label: 'Flame rod fouled — the board cannot sense the flame it has lit', correct: true, why: 'Burners light every time and the flame signal is 0.3 µA against a 1.5 µA threshold. Rectification needs a clean rod and a good ground; an oxidised rod cannot pass enough current for the board to see the fire that is right in front of it.' },
      { id: 'gas', label: 'Gas supply problem', why: 'Manifold pressure is on the nameplate with the burners alight, and they do light — cleanly — every attempt.' },
      { id: 'valve', label: 'Gas valve failing', why: 'The valve opens on every try and the burners light. The board closes it again because it thinks the flame went out.' },
      { id: 'flue', label: 'Blocked flue or failed pressure switch', why: 'The switch makes and holds through the whole sequence, which is why ignition gets as far as it does.' },
    ],
    fixes: [
      { id: 'rod', label: 'Clean or replace the flame rod, verify the ground, prove better than 1.5 µA at steady state', correct: true, cost: 60, why: 'Signal comes up to 4.2 µA, it lights first try and stays lit, and supply air is 108 °F. Note the microamp reading on the ticket — the next person will want to know what good looked like.' },
      { id: 'board', label: 'Replace the ignition control board', cost: 480, why: 'The board is making the correct decision from a real 0.3 µA signal. A new one reads the same fouled rod and locks out the same way.' },
      { id: 'valve', label: 'Replace the gas valve', cost: 640, why: 'The valve opens on command every time and the burners light off it.' },
      { id: 'jumper', label: 'Jumper out the flame sense circuit to keep the heat on', why: 'Absolutely not. That is the proving circuit that shuts the gas off if the fire goes out, and bypassing it fills a supermarket with unburnt gas.' },
    ],
